-- ROUND3 R3-A. Schema part generated by `npm run db:diff` (shadow database
-- only, CLAUDE.md rule 8); the permission grants below are data, added by hand.

-- R3-1 — optional category photo.
-- AlterTable
ALTER TABLE "categories" ADD COLUMN     "photo_url" TEXT;

-- R3-2 — extra price per choice option (default 0: no existing price changes).
-- AlterTable
ALTER TABLE "package_item_options" ADD COLUMN     "extra_price" DECIMAL(12,2) NOT NULL DEFAULT 0;

-- R3-3 — invoice.print: Packing, plus every role and every per-user grant that
-- already has invoice.generate (so nobody loses a print they have today).
-- Admin holds every permission automatically (lib/rbac.ts).
INSERT INTO "permissions" ("key")
VALUES ('invoice.print')
ON CONFLICT ("key") DO NOTHING;

INSERT INTO "role_permissions" ("role_id", "permission_id")
SELECT r."id", p."id"
  FROM "roles" r, "permissions" p
 WHERE r."name" = 'Packing' AND p."key" = 'invoice.print'
ON CONFLICT DO NOTHING;

INSERT INTO "role_permissions" ("role_id", "permission_id")
SELECT rp."role_id", p."id"
  FROM "role_permissions" rp
  JOIN "permissions" g ON g."id" = rp."permission_id" AND g."key" = 'invoice.generate',
       "permissions" p
 WHERE p."key" = 'invoice.print'
ON CONFLICT DO NOTHING;

INSERT INTO "user_permission_overrides" ("user_id", "permission_id", "allow")
SELECT o."user_id", p."id", true
  FROM "user_permission_overrides" o
  JOIN "permissions" g ON g."id" = o."permission_id" AND g."key" = 'invoice.generate',
       "permissions" p
 WHERE p."key" = 'invoice.print' AND o."allow" = true
ON CONFLICT DO NOTHING;
